<x-layouts.app :title="$service->exists ? 'Edit Servis' : 'Catat Servis'" :heading="$service->exists ? 'Edit Servis' : 'Catat Servis'" subheading="Catat perawatan, suku cadang, biaya, dan jadwal berikutnya."><div class="panel"><form method="POST" action="{{ $service->exists ? route('services.update',$service) : route('services.store') }}">@csrf @if($service->exists) @method('PUT') @endif <div class="form-grid"><div><label>Kendaraan</label><select name="vehicle_id" required><option value="">Pilih kendaraan</option>@foreach($vehicles as $vehicle)<option value="{{ $vehicle->id }}" @selected(old('vehicle_id',$service->vehicle_id)==$vehicle->id)>{{ $vehicle->display_name }}</option>@endforeach</select></div><div><label>Tanggal Servis</label><input type="date" name="service_date" value="{{ old('service_date',optional($service->service_date)->format('Y-m-d') ?? now()->toDateString()) }}" required></div><div><label>Jenis Servis</label><input name="service_type" value="{{ old('service_type',$service->service_type) }}" placeholder="Servis berkala / ganti oli" required></div><div><label>Status</label><select name="status"><option value="Selesai" @selected(old('status',$service->status ?? 'Selesai')==='Selesai')>Selesai</option><option value="Diproses" @selected(old('status',$service->status)==='Diproses')>Diproses</option></select></div><div><label>Odometer (km)</label><input type="number" min="0" name="odometer" value="{{ old('odometer',$service->odometer) }}" required></div><div><label>Biaya Jasa (Rp)</label><input type="number" min="0" name="labor_cost" value="{{ old('labor_cost',$service->labor_cost ?? 0) }}" required></div><div><label>Jadwal Servis Berikutnya</label><input type="date" name="next_service_date" value="{{ old('next_service_date',optional($service->next_service_date)->format('Y-m-d')) }}"></div><div><label>Target Odometer Berikutnya (km)</label><input type="number" min="0" name="next_service_odometer" value="{{ old('next_service_odometer',$service->next_service_odometer) }}"></div><div class="full"><label>Keterangan</label><textarea name="description" placeholder="Keluhan, hasil pemeriksaan, atau keterangan lain">{{ old('description',$service->description) }}</textarea></div></div><div class="parts"><div class="panel-head"><div><h2>Suku Cadang</h2><div class="muted">Biaya suku cadang dihitung otomatis saat disimpan.</div></div><button class="btn secondary no-print" type="button" onclick="addPart()">+ Tambah Suku Cadang</button></div><div id="partRows">@php($parts=old('parts',$service->exists ? $service->parts->map(fn($part)=>['name'=>$part->name,'quantity'=>$part->quantity,'unit_price'=>$part->unit_price])->all() : [['name'=>'','quantity'=>1,'unit_price'=>'']]))@foreach($parts as $i=>$part)<div class="part-row"><input name="parts[{{ $i }}][name]" value="{{ $part['name'] }}" placeholder="Nama suku cadang"><input type="number" min="1" name="parts[{{ $i }}][quantity]" value="{{ $part['quantity'] ?? 1 }}" placeholder="Qty"><input type="number" min="0" name="parts[{{ $i }}][unit_price]" value="{{ $part['unit_price'] }}" placeholder="Harga satuan"><button class="icon-button no-print" type="button" onclick="this.parentElement.remove()">Hapus</button></div>@endforeach</div></div><div class="actions"><button class="btn">Simpan Data Servis</button><a class="btn secondary" href="{{ route('services.index') }}">Batal</a></div></form></div><script>let partIndex={{ count($parts) }};function addPart(){document.getElementById('partRows').insertAdjacentHTML('beforeend',`<div class="part-row"><input name="parts[${partIndex}][name]" placeholder="Nama suku cadang"><input type="number" min="1" name="parts[${partIndex}][quantity]" value="1" placeholder="Qty"><input type="number" min="0" name="parts[${partIndex}][unit_price]" placeholder="Harga satuan"><button class="icon-button no-print" type="button" onclick="this.parentElement.remove()">Hapus</button></div>`);partIndex++}</script></x-layouts.app>
